{"path": "textutils.py", "content": "import re

_WORD_RE = re.compile(r"(?:[^\W_]|')+")


def words(text):
    return text.split()


def word_count(text):
    """Map lower-cased words to their counts.

    Words are runs of letters, digits and apostrophes; everything else
    (punctuation, whitespace, underscores) separates words. Runs made only
    of apostrophes are ignored.
    """
    counts = {}
    for match in _WORD_RE.findall(text.lower()):
        if match.strip("'"):
            counts[match] = counts.get(match, 0) + 1
    return counts
"}

